package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.ReleaseVO;

@RequiredArgsConstructor
public class ReleaseValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<ReleaseVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getRelease() {
    return value.flatMap(ReleaseVO::getRelease);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<ReleaseVO> getReleaseValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public ReleaseVO readRelease(final Optional<ObservedIssue> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(ObservedIssue::getReleaseValue).orElseGet(ReleaseVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param release
   * @return
   */
  public T release(ReleaseVO release) {
    this.value = Optional.of(release);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param release
   * @return
   */
  public T release(Optional<ReleaseVO> release) {
    this.value = release;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param release
   * @return
   */
  public T release(String release) {
    this.value = Optional.of(ReleaseVO.from(release));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T releaseNull() {
    this.value = Optional.of(ReleaseVO.nullValue());
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetRelease() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetReleaseIfMatches(final String field) {
    if ("release".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
